let stockMap = new Map();
let queue = [];
let lastTs = 0;
let processed = new Set();

function onMessage(m) {
  const d = JSON.parse(m.data);
  if (processed.has(d.deltaId) || d.ts <= lastTs) return;
  processed.add(d.deltaId);
